/**
 * Pre-decoded pixel data for the recolored Hachiko paw stamp (public/stamp.png
 * on the web), for embedding as a raw PDF Image XObject + SMask in the
 * zero-dependency PDF writer (pdf.ts). Decoded and downsized offline (this
 * repo has no image-decoding dependency to do it at runtime) - RGB and
 * alpha are stored as separate base64 planes of raw, uncompressed 8-bit
 * samples (no /Filter needed, consistent with the rest of this PDF
 * writer, which also emits uncompressed streams).
 */
export const STAMP_WIDTH = 130
export const STAMP_HEIGHT = 117
export const STAMP_RGB_BASE64 = ''
export const STAMP_ALPHA_BASE64 = ''
